   628→  public static reportMessage = async (
   629→    roomId: string,
   630→    event: EventTimelineItem,
   631→    reason: string,
   632→  ) => {
   633→    if (!this.instance) throw new Error("Client not initialized");
   634→    const room = this.instance.getRoom(roomId);
