   893→      const rooms = this.instance.rooms();
   894→      for (const room of rooms) {
   895→        const roomInfo = await room.roomInfo();
   896→        if (roomInfo?.isDirect) {
   897→          const members = await room.members();
   898→          const memberList = members.nextChunk(100000) ?? [];
   899→          const hasUser = memberList.some((member) => member.userId === userId);
   900→          if (hasUser) return room.id();
   901→        }
   902→      }
   903→      return null;
   904→    } catch (error) {
   905→      console.error("Failed to check for existing direct room:", error);
