    24→  static async createWidgetSettings(roomId: string, room: RoomInterface) {
    25→    try {
    26→      const encryptionState = await room.latestEncryptionState();
    27→      const isEncrypted = encryptionState === EncryptionState.Encrypted;
    28→
    29→      const options: VirtualElementCallWidgetProperties = {
    30→        elementCallUrl: "https://call.element.io/room",
    31→        widgetId: `element-call-${roomId}`,
