   117→  static async startCall(
   118→    roomId: string,
   119→    room: RoomInterface,
   120→    client: ClientInterface,
   121→  ) {
   122→    try {
   123→      // Check if there's already an active driver for this room
   124→      const existingDriver = this.widgetDrivers.get(roomId);
   125→      if (existingDriver) {
   126→        console.log("Driver already exists for room:", roomId);
   127→        // Return existing driver instead of creating a new one
   128→        const widgetSettings = await this.createWidgetSettings(roomId, room);
   129→        const url = await this.generateCallUrl(widgetSettings, room, client);
   130→        return { url, driverHandle: existingDriver };
   131→      }
   132→
   133→      const widgetSettings = await this.createWidgetSettings(roomId, room);
   134→
   135→      const driverHandle = this.initializeWidgetDriver(roomId, widgetSettings);
   136→
   137→      const url = await this.generateCallUrl(widgetSettings, room, client);
   138→
   139→      const capabilitiesProvider = this.createCapabilitiesProvider();
   140→
   141→      driverHandle.driver.run(room, capabilitiesProvider).catch(console.error);
   142→
   143→      this.activeCallRoomId = roomId;
   144→
   145→      return { url, driverHandle };
   146→    } catch (error) {
   147→      console.error("Failed to start Element Call:", error);
   148→      throw error;
   149→    }
   150→  }
   151→
   152→  static async endCall(roomId: string) {
   153→    try {
   154→      const driverHandle = this.widgetDrivers.get(roomId);
   155→      if (driverHandle) {
   156→        const widgetId = `element-call-${roomId}`;
   157→
   158→        try {
   159→          // Send hangup message to Element Call
   160→          // This tells Element Call to leave the LiveKit session and remove call.member state
   161→          const hangupMessage = JSON.stringify({
   162→            api: "fromWidget",
   163→            widgetId: widgetId,
   164→            requestId: `hangup-${Date.now()}`,
   165→            action: "im.vector.hangup",
   166→            data: {},
   167→          });
   168→
   169→          await driverHandle.handle.send(hangupMessage);
   170→
   171→          await new Promise((resolve) => setTimeout(resolve, 1000));
   172→
   173→          // Send close message to ensure widget cleanup
   174→          // This is similar to what Swift does with the "close" action
   175→          const closeMessage = JSON.stringify({
   176→            api: "fromWidget",
   177→            widgetId: widgetId,
   178→            requestId: `close-${Date.now()}`,
   179→            action: "io.element.close",
   180→            data: {},
   181→          });
   182→
   183→          await driverHandle.handle.send(closeMessage);
   184→
   185→          await new Promise((resolve) => setTimeout(resolve, 500));
   186→        } catch (err) {
   187→          console.error("Failed to send end call messages:", err);
   188→        }
   189→
   190→        // Cleanup driver
   191→        this.widgetDrivers.delete(roomId);
   192→      }
   193→
   194→      if (this.activeCallRoomId === roomId) this.activeCallRoomId = null;
   195→    } catch (error) {
   196→      console.error("Failed to end call:", error);
   197→    }
   198→  }
   199→
   200→  /**
   201→   * Clean up driver without sending any messages
   202→   * Use this when Element Call has already sent the hangup message
   203→   */
   204→  static async cleanupDriver(roomId: string) {
   205→    this.widgetDrivers.delete(roomId);
   206→    if (this.activeCallRoomId === roomId) this.activeCallRoomId = null;
   207→  }
   208→
   209→  static getActiveCallRoomId() {
