   217→  /**Send message to widget via driver handle */
   218→  static async sendMessageToWidget(roomId: string, message: string) {
   219→    const driverHandle = this.widgetDrivers.get(roomId);
   220→
   221→    if (!driverHandle) {
   222→      console.warn("No driver handle found for room:", roomId);
   223→      return;
   224→    }
   225→
   226→    try {
   227→      await driverHandle.handle.send(message);
   228→    } catch (error) {
   229→      console.error("Failed to send message to widget:", error);
   230→      throw error;
   231→    }
   232→  }
   233→
   234→  static async receiveMessagesFromWidget(roomId: string) {
   235→    const driverHandle = this.widgetDrivers.get(roomId);
   236→
   237→    if (!driverHandle) {
   238→      console.warn("No driver handle found for room:", roomId);
   239→      return;
   240→    }
   241→
   242→    try {
   243→      const message = await driverHandle.handle.recv();
   244→      if (!message) throw new Error("No message received from widget");
   245→
   246→      return message;
   247→    } catch (error) {
   248→      console.error("Failed to receive message from widget:", error);
   249→      throw error;
   250→    }
   251→  }
