    16→const MESSAGE_BRIDGE_SCRIPT = `
    17→            // Setup message bridge between Element Call and React Native
    18→            (function() {
    19→              console.log('🔧 Setting up React Native bridge...');
    20→              
    21→              // Store original postMessage
    22→              const originalPostMessage = window.postMessage.bind(window);
    23→              
    24→              // Flag to prevent re-capturing injected messages
    25→              let isInjecting = false;
    26→              
    27→              // Expose method for injecting messages without re-capture
    28→              window.__rnInjectMessage = function(message) {
    29→                isInjecting = true;
    30→                try {
    31→                  originalPostMessage(message, '*');
    32→                } finally {
    33→                  isInjecting = false;
    34→                }
    35→              };
    36→              
    37→              // Override postMessage to intercept widget messages
    38→              window.postMessage = function(message, targetOrigin) {
    39→                // Don't capture messages that we're injecting from RN
    40→                if (!isInjecting) {
    41→                  try {
    42→                    // Send to React Native if available
    43→                    if (window.ReactNativeWebView) {
    44→                      const messageStr = typeof message === 'string' 
    45→                        ? message 
    46→                        : JSON.stringify(message);
    47→                      window.ReactNativeWebView.postMessage(messageStr);
    48→                      console.log('Sent to RN:', messageStr);
    49→                    }
    50→                  } catch (e) {
    51→                    console.error('Failed to send to RN:', e);
    52→                  }
    53→                }
    54→                
    55→                // Always call original for in-page communication
    56→                try {
    57→                  originalPostMessage(message, targetOrigin);
    58→                } catch (e) {
    59→                  console.error('Failed original postMessage:', e);
    60→                }
    61→              };
    62→            
    63→              console.log('✅ React Native bridge ready');
    64→            })();
    65→            true; // Required for iOS          
    66→  `;
